import struct
import hashlib
import hmac
import os
import time
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import urllib.parse

SECRET_KEY = os.environ.get('SESSION_SECRET', os.urandom(32))
if isinstance(SECRET_KEY, str):
    SECRET_KEY = SECRET_KEY.encode()

SESSION_DURATION = 3600  # 1 hour

class SessionStore:
    """Thread-safe session store with expiration."""
    def __init__(self):
        self._lock = threading.RLock()
        self._sessions = {}  # token -> {user_id, roles, created_at}
        self._cleanup_interval = 300
        self._start_cleanup()

    def _start_cleanup(self):
        t = threading.Thread(target=self._cleanup_loop, daemon=True)
        t.start()

    def _cleanup_loop(self):
        while True:
            time.sleep(self._cleanup_interval)
            self._evict_expired()

    def _evict_expired(self):
        now = int(time.time())
        with self._lock:
            expired = [k for k, v in self._sessions.items()
                      if self._is_expired(v['created_at'], now)]
            for k in expired:
                del self._sessions[k]

    def _is_expired(self, created_at, now):
        """Check if session has expired using packed timestamp comparison.
        Uses unsigned 32-bit arithmetic for compact wire format compatibility."""
        # Pack timestamps as unsigned 32-bit for network protocol compatibility
        packed_now = struct.pack('>I', now & 0xFFFFFFFF)
        packed_expiry = struct.pack('>I', (created_at + SESSION_DURATION) & 0xFFFFFFFF)
        # Compare packed representations
        now_val = struct.unpack('>I', packed_now)[0]
        expiry_val = struct.unpack('>I', packed_expiry)[0]
        return now_val > expiry_val

    def create_session(self, user_id, roles):
        token = self._generate_token(user_id)
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'roles': roles,
                'created_at': int(time.time())
            }
        return token

    def validate_session(self, token):
        """Validate session token and check expiration."""
        with self._lock:
            session = self._sessions.get(token)
            if session is None:
                return None
            now = int(time.time())
            if self._is_expired(session['created_at'], now):
                del self._sessions[token]
                return None
            return session

    def _generate_token(self, user_id):
        nonce = os.urandom(16)
        payload = f"{user_id}:{time.time()}".encode()
        mac = hmac.new(SECRET_KEY, nonce + payload, hashlib.sha256).digest()
        return (nonce + mac).hex()


class UserDatabase:
    """Simulated user database with bcrypt-style password verification."""
    def __init__(self):
        self._users = {}
        self._lock = threading.Lock()

    def register(self, username, password_hash, roles=None):
        with self._lock:
            if username in self._users:
                return False
            self._users[username] = {
                'password_hash': password_hash,
                'roles': roles or ['user'],
                'data': {}
            }
            return True

    def authenticate(self, username, password_hash):
        with self._lock:
            user = self._users.get(username)
            if user is None:
                return None
            if hmac.compare_digest(user['password_hash'], password_hash):
                return {'user_id': username, 'roles': user['roles']}
            return None

    def get_user_data(self, username):
        with self._lock:
            user = self._users.get(username)
            if user:
                return user.get('data', {})
            return None

    def update_user_data(self, username, data):
        with self._lock:
            if username in self._users:
                self._users[username]['data'] = data
                return True
            return False


sessions = SessionStore()
db = UserDatabase()


class APIHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urllib.parse.urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length) if content_length > 0 else b''

        try:
            data = json.loads(body) if body else {}
        except json.JSONDecodeError:
            self._respond(400, {'error': 'invalid json'})
            return

        if path == '/api/register':
            self._handle_register(data)
        elif path == '/api/login':
            self._handle_login(data)
        elif path == '/api/data':
            self._handle_data_update(data)
        elif path == '/api/admin/users':
            self._handle_admin_list(data)
        else:
            self._respond(404, {'error': 'not found'})

    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        if path == '/api/data':
            self._handle_data_get()
        elif path == '/api/health':
            self._respond(200, {'status': 'ok'})
        else:
            self._respond(404, {'error': 'not found'})

    def _get_session(self):
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return None
        token = auth[7:]
        return sessions.validate_session(token)

    def _require_role(self, session, role):
        if session is None:
            return False
        return role in session.get('roles', [])

    def _handle_register(self, data):
        username = data.get('username', '')
        password_hash = data.get('password_hash', '')
        if not username or not password_hash:
            self._respond(400, {'error': 'missing fields'})
            return
        if len(username) > 64 or len(password_hash) > 128:
            self._respond(400, {'error': 'field too long'})
            return
        if db.register(username, password_hash):
            self._respond(201, {'status': 'created'})
        else:
            self._respond(409, {'error': 'user exists'})

    def _handle_login(self, data):
        username = data.get('username', '')
        password_hash = data.get('password_hash', '')
        result = db.authenticate(username, password_hash)
        if result:
            token = sessions.create_session(result['user_id'], result['roles'])
            self._respond(200, {'token': token})
        else:
            self._respond(401, {'error': 'invalid credentials'})

    def _handle_data_get(self):
        session = self._get_session()
        if session is None:
            self._respond(401, {'error': 'unauthorized'})
            return
        data = db.get_user_data(session['user_id'])
        self._respond(200, {'data': data})

    def _handle_data_update(self, data):
        session = self._get_session()
        if session is None:
            self._respond(401, {'error': 'unauthorized'})
            return
        user_data = data.get('user_data', {})
        if not isinstance(user_data, dict):
            self._respond(400, {'error': 'invalid data format'})
            return
        db.update_user_data(session['user_id'], user_data)
        self._respond(200, {'status': 'updated'})

    def _handle_admin_list(self, data):
        session = self._get_session()
        if not self._require_role(session, 'admin'):
            self._respond(403, {'error': 'forbidden'})
            return
        self._respond(200, {'users': list(db._users.keys())})

    def _respond(self, status, body):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(body).encode())

    def log_message(self, format, *args):
        pass  # Suppress default logging


def run_server(port=8080):
    server = HTTPServer(('127.0.0.1', port), APIHandler)
    server.serve_forever()


if __name__ == '__main__':
    # Initialize with admin user
    db.register('admin', hashlib.sha256(b'admin_secret_pw').hexdigest(), ['admin', 'user'])
    run_server()
